const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, BorderStyle, ShadingType, WidthType,
  LevelFormat, Table, TableRow, TableCell
} = require('docx');
const fs = require('fs');

const luxoraBlue = "1B3A5C";
const luxoraGold = "C9A84C";
const lightGray = "F5F5F5";
const darkGray = "333333";
const medGray = "666666";

function heading(text) {
  return new Paragraph({
    spacing: { before: 400, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: luxoraGold } },
    children: [
      new TextRun({ text, font: "Arial", size: 26, bold: true, color: luxoraBlue })
    ]
  });
}

function questionLine(emoji, num, text) {
  return new Paragraph({
    spacing: { before: 300, after: 80 },
    children: [
      new TextRun({ text: `${emoji} ${num}. "${text}"`, font: "Arial", size: 22, bold: true, color: darkGray })
    ]
  });
}

function answerLabel() {
  return new Paragraph({
    spacing: { before: 100, after: 60 },
    children: [
      new TextRun({ text: "BETHANY ANNE'S ANSWER:", font: "Arial", size: 20, bold: true, color: luxoraGold })
    ]
  });
}

function answerPara(text) {
  return new Paragraph({
    spacing: { before: 60, after: 80 },
    children: [
      new TextRun({ text, font: "Arial", size: 20, color: darkGray })
    ]
  });
}

function spacer() {
  return new Paragraph({ spacing: { before: 60, after: 60 }, children: [new TextRun("")]});
}

function divider() {
  return new Paragraph({
    spacing: { before: 200, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: "DDDDDD" } },
    children: [new TextRun("")]
  });
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } }
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // Title block
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 120 },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 36, bold: true, color: luxoraBlue })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 80 },
        children: [new TextRun({ text: "Podcast Question Review", font: "Arial", size: 28, color: luxoraGold })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 400 },
        children: [new TextRun({ text: "Question Ratings + Prepared Answers for Green Questions", font: "Arial", size: 22, color: medGray, italics: true })]
      }),

      // Legend
      new Paragraph({
        spacing: { before: 0, after: 80 },
        children: [new TextRun({ text: "RATING KEY", font: "Arial", size: 22, bold: true, color: luxoraBlue })]
      }),
      new Paragraph({ spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "🟢 Ready to answer as-is", font: "Arial", size: 22 })] }),
      new Paragraph({ spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "🟡 Right direction, needs revision", font: "Arial", size: 22 })] }),
      new Paragraph({ spacing: { before: 40, after: 160 }, children: [new TextRun({ text: "🔴 Pause for now", font: "Arial", size: 22 })] }),

      divider(),

      // PILLAR 1
      heading("PILLAR 1: THE REVENUE LEAK / SECRET SHOPPER HOOK"),

      questionLine("🟢", 1, "You do something called a secret shopper visit for med spas. Walk me through what actually happens when you walk into one of these practices, what are you looking for and what do you usually find?"),
      answerLabel(),
      answerPara("So what I do is I walk in as a regular client. No one knows who I am. I am experiencing the practice exactly the way a paying patient would. I'm paying attention to how I'm greeted, whether the front desk makes eye contact, whether anyone mentions a membership or a package, whether there's a follow-up process. And what I find almost every single time is that the practice has no system. There's no script, no upsell pathway, no retention conversation. The provider is incredible at their craft, but from the moment I walk in to the moment I leave, there are four or five moments where revenue quietly walked out the door. What I document goes into our Confidential Experience Assessment. It's not a gotcha. It's a map of exactly where the money is going."),

      spacer(),

      questionLine("🔴", 2, "What's the most shocking revenue leak you've ever discovered in a med spa that looked successful from the outside?"),

      spacer(),

      questionLine("🟢", 3, "You've said that most med spas doing $500K to $3 million a year are leaving a significant amount of money on the table every single month. Where does that money actually go?"),
      answerLabel(),
      answerPara("It goes to three places consistently. First, it leaves through the front desk because there's no conversion system on incoming calls or consultations. Second, it leaves through one-time clients who never come back because there's no follow-up sequence, no membership offer, no reason to stay connected. And third, it leaks through package and treatment pricing that was never built around lifetime value. Owners are thinking transaction by transaction instead of thinking about what a single client is worth over 12 to 24 months. When you install the right systems, that math changes completely."),

      spacer(),

      questionLine("🟢", 4, "If a med spa owner is listening to this right now and they've never done a revenue leak audit, what's the one question they should be asking themselves today that would tell them if they have a problem?"),
      answerLabel(),
      answerPara("Ask yourself this: do you know your client retention rate? Meaning, of every new patient who walked through your door last year, how many came back a second time? If you don't know that number, or if the answer is less than 60 percent, you have a revenue leak. That one number tells me almost everything I need to know about how a practice is running. And the beautiful thing is, fixing it doesn't require more leads or more ad spend. It requires better systems for the clients you already have."),

      spacer(),

      questionLine("🟡", 5, "You've walked into practices where the calendar is full, the staff is slammed, and the owner is still stressed about cash flow. How is that possible, and what's really going on underneath?"),

      divider(),

      // PILLAR 2
      heading("PILLAR 2: THE LIFETIME CLIENT / MEMBERSHIP FRAMEWORK"),

      questionLine("🟢", 6, "You talk a lot about the difference between a one-time Botox client and a lifetime client. What does that actually look like in practice, and why do most med spas never make that shift?"),
      answerLabel(),
      answerPara("A one-time Botox client comes in, gets their treatment, maybe leaves a review if you ask nicely, and then you hope they come back in four months. There's no guarantee. You're essentially starting over every single time. A lifetime client is someone inside a membership, someone who has a standing monthly investment with the practice. They're pre-committed. Their next appointment isn't a maybe. The revenue is predictable, the relationship is deeper, and their average annual spend is significantly higher. Most med spas never make that shift because the owner doesn't realize a membership is a retention tool, not just a loyalty perk. When it's designed correctly with the right pricing, the right inclusions, and the right 90-day onboarding experience, it completely changes the financial stability of the practice."),

      spacer(),

      questionLine("🟡", 7, "Walk me through what a well-designed membership program actually does for a med spa's revenue. Like, real numbers, what changes?"),
      spacer(),
      questionLine("🟡", 8, "Most med spa owners I talk to think a membership is just a loyalty card or a discount program. What are they getting wrong about what a membership is actually supposed to do?"),
      spacer(),
      questionLine("🔴", 9, "You mentioned that 73% of membership cancellations happen in the first 90 days. What are med spas doing, or not doing, in those first three months that causes people to walk away?"),
      spacer(),
      questionLine("🟡", 10, "What's the psychology behind why a client who pays $399 a month is more valuable to a practice than a client who comes in and spends $600 every few months?"),

      divider(),

      // PILLAR 3
      heading("PILLAR 3: THE FRONT DESK / CONVERSION PROBLEM"),

      questionLine("🟡", 11, "You've said that the front desk is one of the biggest revenue leaks in any med spa. What do you mean by that, and what does the wrong front desk conversation actually cost a practice?"),
      spacer(),
      questionLine("🟡", 12, "What does a bad front desk script sound like versus a good one? Can you give me an example of how that one conversation can change whether someone books or not?"),
      spacer(),
      questionLine("🔴", 13, "A lot of med spa owners hire for personality and assume the rest will work itself out. What's wrong with that approach when it comes to front desk performance?"),
      spacer(),
      questionLine("🟡", 14, "If you could change one thing about how med spas handle the first phone call from a new lead, what would it be?"),

      divider(),

      // PILLAR 4
      heading("PILLAR 4: THE REPUTATION / REVIEWS ENGINE"),

      questionLine("🟡", 15, "You have data showing that one negative review costs a med spa approximately 30 potential clients. Most owners don't take their review strategy seriously, why is that such an expensive mistake?"),
      spacer(),
      questionLine("🟡", 16, "What's the difference between a med spa with 20 Google reviews and one with 200? Like, in real dollars, what does that gap actually mean for the business?"),
      spacer(),
      questionLine("🟢", 17, "Most med spas leave 60 to 75 percent of their potential reviews on the table. Why don't satisfied clients leave reviews, and what's the fix?"),
      answerLabel(),
      answerPara("Because asking for a review feels awkward, and most practices ask at the wrong moment or the wrong way. They'll put a sign on the counter, or someone will say at checkout, 'Feel free to leave us a review!' That is not a system. That's wishful thinking. Satisfied clients don't leave reviews by default because they're busy, they forget, and no one made it easy or urgent. The fix is what we call the Reputation Engine: asking at the exact right moment, which is within that dopamine peak window right after a treatment when the client feels great, and making the ask personal and specific. Not 'leave us a review' but a direct text with their name and a one-tap link. When you systematize that process and you train your team to deliver it consistently, you can triple your review volume inside 90 days."),

      spacer(),

      questionLine("🟡", 18, "You talk about something called the dopamine peak window for asking for reviews. Can you explain what that is and why the timing of when you ask matters so much?"),

      divider(),

      // PILLAR 5
      heading("PILLAR 5: THE OWNER BURNOUT / OPERATOR EXPERIENCE"),

      questionLine("🔴", 19, "You managed three med spa locations and 44 employees at one point. What did burnout actually look like for you, and what finally broke?"),
      spacer(),
      questionLine("🔴", 20, "A lot of med spa owners got into this industry because they love aesthetics or they love people. When did it stop being about that, and what does it feel like when the business is running you instead of the other way around?"),
      spacer(),
      questionLine("🟡", 21, "What's the one thing that owners who are stuck always have in common, is there a pattern you keep seeing?"),
      spacer(),
      questionLine("🔴", 22, "You had a moment where you chose to walk away from a high-level career to build something on your own terms. What did that decision feel like, and what made you finally commit to it?"),

      divider(),

      // PILLAR 6
      heading("PILLAR 6: GROWTH, SCALE, AND BUILDING A SELLABLE ASSET"),

      questionLine("🟢", 23, "You work with practices doing $500K to $3 million a year. What separates the ones who scale past that ceiling from the ones who stay stuck at the same number year after year?"),
      answerLabel(),
      answerPara("The ones who scale have made a decision that they are building a business, not just doing a job they happen to own. That sounds simple but it's actually the biggest mindset shift in this industry. The practices that are stuck are still operating like everything runs through the owner. The owner is the brand, the owner is the closer, the owner is the one who knows the clients. When that owner steps away, the revenue steps away with them. The ones who scale have installed systems: a membership program that creates recurring revenue, a front desk team trained to convert, a follow-up process that runs automatically, and a marketing engine that doesn't rely on the owner to post every day. It's not about working harder. It's about building something that works without you."),

      spacer(),

      questionLine("🟡", 24, "A lot of med spa owners dream about a second location or eventually selling their business. What needs to be true about the business before either of those things is actually possible?"),
      spacer(),
      questionLine("🟢", 25, "What does a growth engine look like inside a med spa that's really running well? What are the systems that make it go?"),
      answerLabel(),
      answerPara("When a practice is running well, there are really five systems working together. You have a membership program creating predictable monthly revenue. You have a package and upsell architecture so every treatment room interaction has a pathway to a larger sale. You have a reputation engine consistently generating reviews and referrals. You have an AI-powered follow-up system nurturing leads and re-engaging lapsed clients automatically. And you have a marketing system that attracts the right clients at the right price point consistently. When all five of those are installed and talking to each other, the owner stops being the ceiling of the business. That's what our 90-Day Growth Engine is built to install."),

      spacer(),

      questionLine("🟡", 26, "If someone is trying to build a practice they could eventually sell, what are the three things they should be building systematically from day one?"),

      divider(),

      // PILLAR 7
      heading("PILLAR 7: THE MARKETING DISCONNECT"),

      questionLine("🟢", 27, "You've worked with med spa owners who've gone through two, three, even four different marketing agencies and still have the same problems. At what point did you realize the agency model itself was broken for this industry, and what does actually solving it look like?"),
      answerLabel(),
      answerPara("I realized it when I kept seeing the same pattern: owner hires an agency, the agency runs ads, leads come in, and the practice still struggles. The agency points to the lead count and says the campaign worked. The owner looks at their bank account and says something is wrong. And both of them are right because the problem was never the leads. It was everything that happened after the lead. A marketing agency working in isolation cannot fix a conversion problem. They can't fix a retention problem. They can't build a membership program or train your front desk or install a follow-up sequence. That's not their job. The real solve is an integrated approach where marketing, operations, sales conversion, and retention are all moving together. That's what we do, and it's why our clients see results that agencies working alone simply cannot deliver."),

      spacer(),

      questionLine("🟡", 28, "What's the difference between marketing that makes a practice look good and marketing that actually makes the phone ring and the calendar fill?"),
      spacer(),
      questionLine("🟢", 29, "When you work with a practice, you're not just fixing the marketing, you're going in and looking at operations, conversion, retention, the full picture. Why does that integrated approach get results that a social media team or an ad agency working in isolation never could?"),
      answerLabel(),
      answerPara("Because revenue isn't a marketing problem. It's a systems problem. An agency can drive a hundred leads a month and if the front desk isn't trained to convert, if there's no follow-up sequence, if there's no membership offer, if the pricing structure doesn't support upsells, those leads evaporate. You've paid for an audience and then failed to build a business with them. When we come in, we're looking at the full revenue cycle: how clients find you, how they're converted, what they're offered, how they're retained, and what they tell their friends. That's not something a single-function vendor can solve. It requires someone willing to get into the operations and install the infrastructure. That's what makes our work different and why the results stick."),

      spacer(),

      questionLine("🟢", 30, "If a med spa owner came to you today with $5,000 to spend on growing their business, they can put it anywhere. Where would you tell them to put it first, and why?"),
      answerLabel(),
      answerPara("I would tell them to put it into their existing client base before they spend a single dollar on new leads. Your most profitable growth is always sitting in your current database. Those are people who already trust you, who have already bought from you, who already know what you do. If you don't have a membership program, build one. If you don't have a follow-up sequence for lapsed clients, install one. If you're not systematically asking for reviews and referrals, start there. You could re-engage 15 to 20 percent of your lapsed client list with a single well-timed campaign. That return is almost always faster and more profitable than running cold ads to strangers. New leads are expensive. Warm clients who already like you are a completely different conversation."),

      spacer(),

      // Footer note
      new Paragraph({
        spacing: { before: 400, after: 0 },
        alignment: AlignmentType.CENTER,
        children: [
          new TextRun({ text: "The Luxora Collective | theluxoracollective.co | Prepared for Podcast Production", font: "Arial", size: 18, color: medGray, italics: true })
        ]
      })

    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/mnt/user-data/outputs/TLC_Podcast_Question_Review.docx", buffer);
  console.log("Done!");
});

