const {
  Document, Packer, Paragraph, TextRun,
  AlignmentType, BorderStyle, ShadingType, WidthType,
  Table, TableRow, TableCell, VerticalAlign
} = require('docx');
const fs = require('fs');

const NAVY    = "1B3A5C";
const GOLD    = "C9A84C";
const WHITE   = "FFFFFF";
const OFFWHITE = "FAFAF7";
const NAVY_LIGHT = "E8EEF5";  // light navy tint for answer blocks
const GOLD_LIGHT = "FDF6E3";  // light gold tint
const CHARCOAL = "2C2C2C";

const border = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders = { top: border, bottom: border, left: border, right: border };

// Full-width colored banner paragraph using table (1 col)
function banner(text, bgColor, textColor, textSize = 26) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorders,
            shading: { fill: bgColor, type: ShadingType.CLEAR },
            margins: { top: 160, bottom: 160, left: 200, right: 200 },
            children: [
              new Paragraph({
                alignment: AlignmentType.LEFT,
                children: [new TextRun({ text, font: "Arial", size: textSize, bold: true, color: textColor })]
              })
            ]
          })
        ]
      })
    ]
  });
}

function titleBanner(title, subtitle) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorders,
            shading: { fill: NAVY, type: ShadingType.CLEAR },
            margins: { top: 320, bottom: 320, left: 360, right: 360 },
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                spacing: { after: 80 },
                children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 40, bold: true, color: GOLD })]
              }),
              new Paragraph({
                alignment: AlignmentType.CENTER,
                spacing: { after: 80 },
                children: [new TextRun({ text: "Podcast Question Review", font: "Arial", size: 28, color: WHITE })]
              }),
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: "Question Ratings + Prepared Answers", font: "Arial", size: 20, color: "CCCCCC", italics: true })]
              }),
            ]
          })
        ]
      })
    ]
  });
}

function legendBlock() {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorders,
            shading: { fill: GOLD_LIGHT, type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 200, right: 200 },
            children: [
              new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: "RATING KEY", font: "Arial", size: 20, bold: true, color: NAVY })] }),
              new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: "🟢  Ready to answer as-is", font: "Arial", size: 20, color: CHARCOAL })] }),
              new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: "🟡  Right direction, needs revision", font: "Arial", size: 20, color: CHARCOAL })] }),
              new Paragraph({ children: [new TextRun({ text: "🔴  Pause for now", font: "Arial", size: 20, color: CHARCOAL })] }),
            ]
          })
        ]
      })
    ]
  });
}

function pillarHeader(text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorders,
            shading: { fill: NAVY, type: ShadingType.CLEAR },
            margins: { top: 140, bottom: 140, left: 200, right: 200 },
            children: [
              new Paragraph({
                children: [new TextRun({ text: text.toUpperCase(), font: "Arial", size: 22, bold: true, color: WHITE })]
              })
            ]
          })
        ]
      })
    ]
  });
}

function questionBlock(emoji, num, text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: {
              top: { style: BorderStyle.NONE, size: 0, color: WHITE },
              bottom: { style: BorderStyle.SINGLE, size: 2, color: "DDDDDD" },
