const {
  Document, Packer, Paragraph, TextRun,
  AlignmentType, BorderStyle, ShadingType, WidthType,
  Table, TableRow, TableCell
} = require('docx');
const fs = require('fs');

const NAVY     = "1B3A5C";
const GOLD     = "C9A84C";
const WHITE    = "FFFFFF";
const OFFWHITE = "FAFAF7";
const NAVY_LIGHT = "E8EEF5";
const GOLD_LIGHT = "FDF6E3";
const CHARCOAL = "2C2C2C";
const GREEN_BORDER = "27AE60";
const YELLOW_BORDER = "F39C12";
const RED_BORDER = "E74C3C";

const noB = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders = { top: noB, bottom: noB, left: noB, right: noB };

function titleBanner() {
  return new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360],
    rows: [new TableRow({ children: [new TableCell({
      borders: noBorders,
      shading: { fill: NAVY, type: ShadingType.CLEAR },
      margins: { top: 320, bottom: 320, left: 360, right: 360 },
      children: [
        new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 80 }, children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 40, bold: true, color: GOLD })] }),
        new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 80 }, children: [new TextRun({ text: "Podcast Question Review", font: "Arial", size: 28, color: WHITE })] }),
        new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Question Ratings + Prepared Answers", font: "Arial", size: 20, color: "CCCCCC", italics: true })] }),
      ]
    })]})],
  });
}

function legendBlock() {
  return new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360],
    rows: [new TableRow({ children: [new TableCell({
      borders: noBorders,
      shading: { fill: GOLD_LIGHT, type: ShadingType.CLEAR },
      margins: { top: 120, bottom: 120, left: 200, right: 200 },
      children: [
        new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: "RATING KEY", font: "Arial", size: 20, bold: true, color: NAVY })] }),
        new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: "🟢  Ready to answer as-is", font: "Arial", size: 20, color: CHARCOAL })] }),
        new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: "🟡  Right direction, needs revision", font: "Arial", size: 20, color: CHARCOAL })] }),
        new Paragraph({ children: [new TextRun({ text: "🔴  Pause for now (personal story only you can tell)", font: "Arial", size: 20, color: CHARCOAL })] }),
      ]
    })]})],
  });
}

function pillarHeader(text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360],
    rows: [new TableRow({ children: [new TableCell({
      borders: noBorders,
      shading: { fill: NAVY, type: ShadingType.CLEAR },
      margins: { top: 140, bottom: 140, left: 200, right: 200 },
      children: [new Paragraph({ children: [new TextRun({ text: text.toUpperCase(), font: "Arial", size: 22, bold: true, color: WHITE })] })]
    })]})],
  });
}

function questionBlock(emoji, num, text) {
  const borderColor = emoji === "🟢" ? GREEN_BORDER : emoji === "🟡" ? YELLOW_BORDER : RED_BORDER;
  return new Table({
    width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360],
    rows: [new TableRow({ children: [new TableCell({
